mapper.select:
select unQualified, total, (case total when 0 THEN 0 /*总数为0时，合格率为0*/ else ROUND((1-(unQualified/total))*100,2) end)as rate, pageType from( /*1 证件类型合格率*/ select count(temp.SUBMIT_STATUS) as total, count(temp.SUBMIT_STATUS) - ifnull(sum(temp.lateNums),0) as unQualified, '1' as pageType /*1 证件类型*/ from( select case when ces.PERSONAL_IDENTIFY_TYPE in ('00','01') then 1 else 0 end lateNums, /*统计不符合条件数*/ ces.SUBMIT_STATUS from CHB_EQU_SUB ces where ces.STATUS in ('01','02') and ces.SUBMIT_STATUS in ('02','03') and ces.HOLDER_MARK = '01' and ces.HOLDER_TYPE in ('01','02','03')
#{orgCode,jdbcType=VARCHAR}
and STR_TO_DATE(DATE_FORMAT(ces.SUBMIT_TIME, '%Y-%m-%d'), '%Y-%m-%d') <= STR_TO_DATE(#{searchDate},'%Y-%m-%d') ) temp
union all /*2 证件匹配合格率*/ select temp2.total as total, temp1.unQualified, '2' as pageType /*2 证件匹配*/ from( select ifnull(sum(counts),0) as unQualified from ( select ces1.PERSONAL_IDENTIFY_TYPE, ces1.INSTITUTION_IDENTIFY_TYPE, ces1.IDENTIFY_NUMBER, count(1) counts from CHB_EQU_SUB ces1 where ces1.STATUS in ('01','02') and ces1.SUBMIT_STATUS in ('02','03')
#{orgCode,jdbcType=VARCHAR}
and STR_TO_DATE(DATE_FORMAT(ces1.SUBMIT_TIME, '%Y-%m-%d'), '%Y-%m-%d') <= STR_TO_DATE(#{searchDate},'%Y-%m-%d') group by ces1.PERSONAL_IDENTIFY_TYPE, ces1.INSTITUTION_IDENTIFY_TYPE, ces1.IDENTIFY_NUMBER having count(1) > 1 ) cc ) temp1,( select count(1) total from CHB_EQU_SUB ces2 where ces2.STATUS in ('01','02') and ces2.SUBMIT_STATUS in ('02','03')
#{orgCode,jdbcType=VARCHAR}
and STR_TO_DATE(DATE_FORMAT(ces2.SUBMIT_TIME, '%Y-%m-%d'), '%Y-%m-%d') <= STR_TO_DATE(#{searchDate},'%Y-%m-%d') ) temp2
union all /*3 及时性合格率*/ select count(temp.SEND_STATUS) as total, ifnull(sum(temp.lateNums),0) as unQualified, '3' as pageType /*3 及时性*/ from( select case when ciis.SUBMIT_TIME > ciis.SUBMIT_DEADLINE then 1 else 0 end lateNums, /*统计不符合条件数*/ ciis.SEND_STATUS from CHB_INVESTHOLD_INFO_SUB ciis where ciis.STATUS in ('01','02') and ciis.SEND_STATUS in ('02','03')
#{orgCode,jdbcType=VARCHAR}
and STR_TO_DATE(DATE_FORMAT(ciis.SUBMIT_TIME, '%Y-%m-%d'), '%Y-%m-%d') <= STR_TO_DATE(#{searchDate},'%Y-%m-%d') ) temp ) aa

select ces.INDENTIFY_MARK indentifyMark, ces.HOLDER_MARK holderMark, ces.HOLDER_TYPE holderType, ces.PERSONAL_IDENTIFY_TYPE personalIdentifyType from CHB_EQU_SUB ces where ces.STATUS in ('01','02') and ces.SUBMIT_STATUS in ('02','03') and ces.HOLDER_MARK = '01' and ces.HOLDER_TYPE in ('01','02','03')
#{orgCode,jdbcType=VARCHAR}
and STR_TO_DATE(DATE_FORMAT(ces.SUBMIT_TIME, '%Y-%m-%d'), '%Y-%m-%d') <= STR_TO_DATE(#{searchDate},'%Y-%m-%d') and ces.PERSONAL_IDENTIFY_TYPE not in ('00','01')

with temp as ( select ces1.PERSONAL_IDENTIFY_TYPE, ces1.INSTITUTION_IDENTIFY_TYPE, ces1.IDENTIFY_NUMBER, count(1) counts from CHB_EQU_SUB ces1 where ces1.STATUS in ('01','02') and ces1.SUBMIT_STATUS in ('02','03')
#{orgCode,jdbcType=VARCHAR}
and STR_TO_DATE(ces1.SUBMIT_TIME, '%Y-%m-%d') <= STR_TO_DATE(#{searchDate},'%Y-%m-%d') group by ces1.PERSONAL_IDENTIFY_TYPE, ces1.INSTITUTION_IDENTIFY_TYPE, ces1.IDENTIFY_NUMBER having count(1) > 1 )
select ces.REGIST_BANK_CODE registBankCode, ces.INDENTIFY_MARK indentifyMark, ces.PERSONAL_IDENTIFY_TYPE personalIdentifyType, ces.INSTITUTION_IDENTIFY_TYPE institutionIdentifyType, ifnull(ces.PERSONAL_IDENTIFY_TYPE,ces.INSTITUTION_IDENTIFY_TYPE) identifyType, ces.IDENTIFY_NUMBER identifyNumber, ces.HOLDER_NAME holderName from CHB_EQU_SUB ces INNER join temp on ifnull(ces.personal_identify_type,'0')=ifnull(temp.personal_identify_type,'0') and ifnull(ces.institution_identify_type,'0')=ifnull(temp.institution_identify_type,'0') and ces.identify_number=temp.identify_number where ces.STATUS in ('01','02') and ces.SUBMIT_STATUS in ('02','03') and STR_TO_DATE(DATE_FORMAT(ces.SUBMIT_TIME, '%Y-%m-%d'), '%Y-%m-%d') <= STR_TO_DATE(#{searchDate},'%Y-%m-%d')
#{orgCode,jdbcType=VARCHAR}
order by identifyType asc ,identifyNumber asc

select ciis.PRD_REGIST_CODE prdRegistCode, ciis.INDENTIFY_MARK indentifyMark, ciis.HOLD_DATE holdDate, ciis.SEND_STATUS sendStatus, ciis.SUBMIT_TIME submitTime from CHB_INVESTHOLD_INFO_SUB ciis where ciis.STATUS in ('01','02') and ciis.SEND_STATUS in ('02','03') and ciis.SUBMIT_TIME > ciis.SUBMIT_DEADLINE
#{orgCode,jdbcType=VARCHAR}
and STR_TO_DATE(DATE_FORMAT(ciis.SUBMIT_TIME, '%Y-%m-%d'), '%Y-%m-%d') <= STR_TO_DATE(#{searchDate},'%Y-%m-%d')

mapper.sql:
WITH END_SUB AS ( SELECT PROD_ID, MDATE FROM ( SELECT CHB_PRD_END_SUB.PROD_ID, CHB_PRD_END_SUB.MDATE, CHB_PRD_END_SUB.STATUS, ROW_NUMBER() over( partition BY CHB_PRD_END_SUB.PROD_ID ORDER BY CHB_PRD_END_SUB.UPDATE_TIME DESC) AS rowno FROM CHB_PRD_END_SUB
#{orgCode,jdbcType=VARCHAR}
) t1 WHERE rowno = 1 AND STATUS != #{statusDel,jdbcType=VARCHAR} )

mapper.select:
SELECT INVESTHOLD_SUB.PRODID, INVESTHOLD_SUB.INDENTIFY_MARK, INVESTHOLD_SUB.HOLD_DATE FROM ( SELECT PRODID, INDENTIFY_MARK, HOLD_DATE FROM ( SELECT PRODID, INDENTIFY_MARK, HOLD_DATE, STATUS, ROW_NUMBER() over( partition BY PRODID, INDENTIFY_MARK,HOLD_DATE ORDER BY UPDATE_TIME DESC) AS rowno FROM CHB_INVESTHOLD_INFO_SUB WHERE STR_TO_DATE(DATE_FORMAT(HOLD_DATE, '%Y-%m-%d'), '%Y-%m-%d') = STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d')
#{orgCode,jdbcType=VARCHAR}
) temp1 WHERE rowno = 1 AND STATUS != #{statusDel,jdbcType=VARCHAR} ) as INVESTHOLD_SUB LEFT JOIN ( SELECT PROD_ID, MDATE FROM ( SELECT CHB_PRD_END_SUB.PROD_ID, CHB_PRD_END_SUB.MDATE, CHB_PRD_END_SUB.STATUS, ROW_NUMBER() over( partition BY CHB_PRD_END_SUB.PROD_ID ORDER BY CHB_PRD_END_SUB.UPDATE_TIME DESC) AS rowno FROM CHB_PRD_END_SUB) temp2 WHERE rowno = 1 AND STATUS != #{statusDel,jdbcType=VARCHAR} ) END_SUB ON INVESTHOLD_SUB.PRODID = END_SUB.PROD_ID LEFT JOIN CHB_PRD_BASEINFO CP ON INVESTHOLD_SUB.PRODID = CP.PROD_ID WHERE ((CP.ISSUING_STATUS != #{issuingSuccess,jdbcType=VARCHAR} OR CP.ISSUING_STATUS IS NULL) OR (END_SUB.MDATE IS NOT NULL AND END_SUB.MDATE < INVESTHOLD_SUB.HOLD_DATE))

SELECT INVESTHOLD_SUB.PRODID, INVESTHOLD_SUB.INDENTIFY_MARK, INVESTHOLD_SUB.HOLD_DATE FROM ( SELECT PRODID, INDENTIFY_MARK, HOLD_DATE FROM ( SELECT PRODID, INDENTIFY_MARK, HOLD_DATE, STATUS, ROW_NUMBER() over( partition BY PRODID, INDENTIFY_MARK,HOLD_DATE ORDER BY UPDATE_TIME DESC) AS rowno FROM CHB_INVESTHOLD_INFO_SUB WHERE STR_TO_DATE(DATE_FORMAT(HOLD_DATE, '%Y-%m-%d'), '%Y-%m-%d') = STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d')
#{orgCode,jdbcType=VARCHAR}
) temp1 WHERE rowno = 1 AND STATUS != #{statusDel,jdbcType=VARCHAR} ) as INVESTHOLD_SUB

mapper.sql:
WITH OBJREC AS ( select PROD_REGIST_CODE, SINGLE_TOTAL, LEGAL_TOTAL, UNLEGAL_TOTAL, VDATE from ( SELECT PROD_REGIST_CODE, SINGLE_TOTAL, LEGAL_TOTAL, UNLEGAL_TOTAL, VDATE FROM ( SELECT @rownum :=@rownum +1 rownum, A.PROD_REGIST_CODE, A.SINGLE_TOTAL, A.LEGAL_TOTAL, A.UNLEGAL_TOTAL, B.VDATE, A.STATUS, IF (@PROD_REGIST_CODE = A.PROD_REGIST_CODE, @rank :=@rank + 1, @rank :=1 ) AS rowno, @PROD_REGIST_CODE := A.PROD_REGIST_CODE FROM ( SELECT * FROM CHB_PRD_RAISETOT_SUB ORDER BY PROD_REGIST_CODE, UPDATE_TIME ) A
LEFT JOIN CHB_PRD_BASEINFO B ON A.PROD_ID = B.PROD_ID left join ( SELECT @rownum := 0, @PROD_REGIST_CODE := NULL, @rank := 0 ) tmp on 1=1 WHERE STR_TO_DATE(DATE_FORMAT(B.VDATE, '%Y-%m-%d'), '%Y-%m-%d') = STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d')
#{orgCode,jdbcType=VARCHAR}
) temp1 WHERE rowno = 1 AND STATUS != #{statusDel,jdbcType=VARCHAR} ) as a )

WITH END_SUB AS ( SELECT PROD_ID, MDATE FROM ( SELECT CHB_PRD_END_SUB.PROD_ID, CHB_PRD_END_SUB.MDATE, CHB_PRD_END_SUB.STATUS, ROW_NUMBER() over( partition BY CHB_PRD_END_SUB.PROD_ID ORDER BY CHB_PRD_END_SUB.UPDATE_TIME DESC) AS rowno FROM CHB_PRD_END_SUB
#{orgCode,jdbcType=VARCHAR}
) as t1 WHERE rowno = 1 AND STATUS != #{statusDel,jdbcType=VARCHAR} )
